    for o in c.outputs:
        txt=''
        if o.get('output_type')=='stream': txt=o.get('text','')
        elif 'data' in o:
            d=o['data']; txt=d.get('text/plain','') if isinstance(d,dict) else ''
            txt=txt if isinstance(txt,str) else str(txt)
        elif o.get('output_type')=='error': txt=o.get('evalue','')+str(o.get('traceback',''))
        if cyr.search(txt): bad.append((i,o.get('output_type')))
print('Cyrillic in outputs:',bad)
imgs=sorted(Path('outputs/eda/figures').glob('*.png'))
